INSERT INTO `servers` (`slug`, `position`, `name`, `summary`, `description`, `transport`, `language`, `repo`, `status`, `config`) VALUES ('portfolio', 0, 'mcp-portfolio', 'このサイト自身。掲載している MCP サーバーの一覧と詳細を返す', 'このポートフォリオサイトはリモート MCP サーバーでもあります。Claude に URL を渡すと、ここに載っているサーバーの一覧やツール定義を読めます。Streamable HTTP のステートレス構成で、読み取り専用のツールを 2 つ提供します。', 'streamable-http', 'TypeScript', 'https://github.com/Kaaaaazuya/mcp-shelf', 'active', '{"mcpServers":{"portfolio":{"type":"http","url":"{{MCP_URL}}"}}}');
--> statement-breakpoint
INSERT INTO `tools` (`server_slug`, `name`, `position`, `description`, `input_schema`) VALUES ('portfolio', 'list_servers', 0, '掲載している MCP サーバーの一覧（slug、名前、要約、トランスポート、状態）を返す', '{"type":"object","properties":{},"additionalProperties":false}');
--> statement-breakpoint
INSERT INTO `tools` (`server_slug`, `name`, `position`, `description`, `input_schema`) VALUES ('portfolio', 'get_server', 1, 'slug で指定した MCP サーバーの詳細（説明、ツール定義、接続設定）を返す', '{"type":"object","properties":{"slug":{"type":"string","description":"list_servers が返す slug"}},"required":["slug"],"additionalProperties":false}');
--> statement-breakpoint
INSERT INTO `servers` (`slug`, `position`, `name`, `summary`, `description`, `transport`, `language`, `repo`, `status`, `config`) VALUES ('agentguard', 1, 'AgentGuard FS', 'CUE で書いたポリシーに従って、AI エージェントのローカルファイル操作を操作ごとに許可・拒否する', 'AI エージェントにローカルファイル操作（read_file、write_file、list_files、delete_file）を提供し、CUE で書いたポリシーに従って操作ごとに許可・拒否する MCP サーバーです。デフォルト拒否・拒否優先で、deny ルールは大文字小文字と Unicode 正規化の違いを無視して照合します。操作は --root のディレクトリ内に限られ、symlink はパスのどこにあっても拒否します（Linux は openat2、macOS は O_NOFOLLOW_ANY）。読み書きはサイズ上限付きの UTF-8 テキストのみです。Linux 5.6 以上または macOS 11 以上で動きます。', 'stdio', 'Go', 'https://github.com/Kaaaaazuya/agent-guard-fs', 'experimental', '{"mcpServers":{"agentguard":{"command":"/absolute/path/to/agent-guard-fs/bin/agentguard","args":["--root","/absolute/path/to/project","--policy","/absolute/path/to/policy.cue"]}}}');
--> statement-breakpoint
INSERT INTO `tools` (`server_slug`, `name`, `position`, `description`, `input_schema`) VALUES ('agentguard', 'read_file', 0, 'Read a UTF-8 text file that the policy allows.', '{"type":"object","properties":{"path":{"type":"string","description":"the path relative to the root, such as src/main.go"}},"required":["path"],"additionalProperties":false}');
--> statement-breakpoint
INSERT INTO `tools` (`server_slug`, `name`, `position`, `description`, `input_schema`) VALUES ('agentguard', 'write_file', 1, 'Create or replace a UTF-8 text file that the policy allows. Parent directories are not created.', '{"type":"object","properties":{"path":{"type":"string","description":"the path relative to the root, such as src/main.go"},"content":{"type":"string","description":"the full UTF-8 text to store at the path"}},"required":["path","content"],"additionalProperties":false}');
--> statement-breakpoint
INSERT INTO `tools` (`server_slug`, `name`, `position`, `description`, `input_schema`) VALUES ('agentguard', 'list_files', 2, 'List the direct children of a directory that the policy allows. Entries the policy hides are omitted.', '{"type":"object","properties":{"path":{"type":"string","description":"the path relative to the root, such as src/main.go"}},"required":["path"],"additionalProperties":false}');
--> statement-breakpoint
INSERT INTO `tools` (`server_slug`, `name`, `position`, `description`, `input_schema`) VALUES ('agentguard', 'delete_file', 3, 'Delete a regular file that the policy allows. Directories and links are not deleted.', '{"type":"object","properties":{"path":{"type":"string","description":"the path relative to the root, such as src/main.go"}},"required":["path"],"additionalProperties":false}');
